import{z as i,x as A,o as t,c as p,q as s,j as B,D as e,d as r,s as l,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"欧拉方程与横截条件","description":"","frontmatter":{"title":"欧拉方程与横截条件","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/euler-transversality.md","filePath":"econ/euler-transversality.md","lastUpdated":1791413859000}'),d={name:"econ/euler-transversality.md"};function m(C,a,u,c,T,_){const n=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="欧拉方程与横截条件" tabindex="-1">欧拉方程与横截条件 <a class="header-anchor" href="#欧拉方程与横截条件" aria-label="Permalink to &quot;欧拉方程与横截条件&quot;">​</a></h1><div class="epigraph"><p>欧拉管相邻两期的交换；横截管「无穷远的资本不值钱」。少一条，庞氏或爆炸路径会混进一阶条件。</p><footer>—— Ramsey, A Mathematical Theory of Saving, Economic Journal 1928；Stokey and Lucas, Recursive Methods, 第 4 章；对照 Weitzman 对横截的讨论</footer></div><p><a href="/econ/vfi-pi">上一课</a>用迭代算出 \\(V\\) 与 \\(g\\)。许多宏观模型并不显式存 \\(V\\)，而是写欧拉再拼一个边界。本课缺口是：<strong>欧拉不是全部一阶条件</strong>。内部解的相邻交换加上横截（TVC），才对应最优路径。不重做网格算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>包络把 \\(V&#39;(k)\\) 换成 \\(u&#39;(c)\\)，相邻两期给出</p> \\[u&#39;(c_t)=\\beta\\mathrm{E}_t\\bigl[u&#39;(c_{t+1})(1+r_{t+1})\\bigr]. \\]<p>这与 <a href="/econ/consumption-euler">跨期欧拉</a> 同一条，只是现在 \\(r\\) 可以是资本边际产出。序列问题还有「不要在无穷远处留下正值资本」：典型 TVC 为 \\(\\lim_{t\\to\\infty}\\mathrm{E}[\\beta^t u&#39;(c_t)k_{t+1}]=0\\)。欧拉加上资本积累，通解常含爆炸项；TVC 把它关掉，留下稳定流形上的路径。缺口是钉这条分工，而不是再推一次边际效用比。</p><p><span class="marginnote">欧拉方程翻译成大白话：「今天少吃一口、明天连本带利多吃一口，两边的遗憾要打平」。\\(u&#39;(c_t)\\) 是今天那口的遗憾，\\(\\beta(1+r)u&#39;(c_{t+1})\\) 是明天那口贴回今天的遗憾——两不等，就还有套利空间可挪。</span></p><p><span class="marginnote">确定性 Ramsey 的横截与横截条件在无限期规划里几乎等价于「影子价格与存量的积贴现后趋于零」。理性泡沫课已经从资产价格写过爆炸解；这里是实物资本的同一逻辑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内部解：对 \\(k_{t+1}\\) 变分，得到欧拉。约束解：欧拉变不等式，与 KKT 乘子一起。TVC 不能从有限期的终端条件 \\(k_{T+1}=0\\) 直接「令 \\(T\\to\\infty\\)」而不加正则——存在反例使欧拉路径满足极限形式却非最优。实践中：线性化后丢掉不稳定根，等于强加有界性，常与 TVC 对齐。随机情形写期望形式。政府债务的横截下一单元才接到可持续性，本课先用私人资本。</p>',11)),(t(),B(o,null,{default:e(()=>[l(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E6%AC%A7%E6%8B%89%3A%20%E4%B8%A4%E6%9C%9F%E4%BA%A4%E6%8D%A2%22%5D%20--%3E%20FAM%5B%22%E4%B8%80%E6%97%8F%E8%B7%AF%E5%BE%84%22%5D%0A%20%20TVC%5B%22%E6%A8%AA%E6%88%AA%20%2F%20%E6%9C%89%E7%95%8C%22%5D%20--%3E%20SEL%5B%22%E6%8C%91%E5%87%BA%E6%9C%80%E4%BC%98%22%5D%0A%20%20FAM%20--%3E%20SEL%0A%20%20SEL%20--%3E%20SS%5B%22%E7%A8%B3%E6%80%81%E6%88%96%E5%B9%B3%E7%A8%B3%E5%88%86%E5%B8%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与贝尔曼的对齐：最优政策自动满足欧拉（内部）与 TVC（正则下）。从欧拉反推 \\(V\\) 不是本课任务；从欧拉求解路径是后课线性化与扰动的入口。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是变分只比较「挪一单位到下一期」。无穷远的挪动不在相邻比较里，必须另加。庞氏：永远滚债务、永远不还，可以满足一期一期的欧拉，却把资源从无穷远偷到今天。TVC 禁止这种偷。资产定价里排除泡沫，宏观里排除爆炸资本，是同一个「影子价格乘存量要贴现掉」的要求。",-1)),a[6]||(a[6]=E("p",null,"代表性个体完全市场下，加总欧拉即总量欧拉。异质加约束时，欧拉只在不受约束的人身上成立，加总不再是单一 \\(u'(C)\\)——那是 HANK 的缺口，本课先把代表性内部解写清。",-1)),(t(),B(o,null,{default:e(()=>[l(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOVE%5B%22%E5%8F%98%E5%88%86%3A%20%E6%8C%AA%E4%B8%80%E5%8D%95%E4%BD%8D%E5%88%B0%E4%B8%8B%E4%B8%80%E6%9C%9F%22%5D%20--%3E%20EU%5B%22%E6%AC%A7%E6%8B%89%E5%8F%AA%E6%AF%94%E8%BE%83%E7%9B%B8%E9%82%BB%E4%B8%A4%E6%9C%9F%22%5D%0A%20%20EU%20--%3E%20PON%5B%22%E5%BA%9E%E6%B0%8F%3A%20%E6%B0%B8%E8%BF%9C%E6%BB%9A%E5%80%BA%E5%8A%A1%E4%B8%8D%E8%BF%98%E6%9C%AC%22%5D%0A%20%20PON%20--%3E%20PASSES%5B%22%E4%B8%80%E6%9C%9F%E4%B8%80%E6%9C%9F%E7%9C%8B%3A%20%E6%AF%8F%E6%AD%A5%E9%83%BD%E5%90%88%E8%A7%84%22%5D%0A%20%20PASSES%20--%3E%20FAR%5B%22%E4%BB%A3%E4%BB%B7%E5%85%A8%E5%A0%86%E5%88%B0%E6%97%A0%E7%A9%B7%E8%BF%9C%22%5D%0A%20%20FAR%20--%3E%20TVC%5B%22TVC%3A%20%E8%B4%B4%E7%8E%B0%E5%BD%B1%E5%AD%90%E4%BB%B7%E5%80%BC%E9%A1%BB%E8%B6%8B%E4%BA%8E%E9%9B%B6%22%5D%0A%20%20TVC%20--%3E%20KILL%5B%22%E7%88%86%E7%82%B8%E8%B7%AF%E5%BE%84%E8%A2%AB%E5%85%B3%E6%8E%89%22%5D%0A%20%20KILL%20--%3E%20SADDLE%5B%22%E7%95%99%E4%B8%8B%E9%9E%8D%E7%82%B9%E4%B8%8A%E7%9A%84%E6%9C%80%E4%BC%98%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">常见误区：初学者容易以为「每期都满足欧拉的路径就是最优路径」。庞氏骗局每一步都局部理性——借新还旧、当期消费照常——代价全部记到无穷远的账上。欧拉看不清无穷远，TVC 才是把这条逃逸通道关上的那道门。</span></p><p><span class="marginnote">Cass–Koopmans 与 Ramsey 计划者：欧拉给出 \\(c\\) 相对 \\(k\\) 的斜率，TVC 加鞍点稳定给出从 \\(k_0\\) 出发的唯一正向路径。Blanchard–Kahn 是这条几何的线性随机版。</span></p><p><span class="marginnote">数字实例：若资本存量以每年 6% 增长、贴现因子 \\(\\beta=0.96\\)，则 \\(\\beta^t k_{t+1}\\) 每年大约乘上 \\(0.96\\times1.06\\gt 1\\)——贴现追不上积累，影子价值越滚越大，TVC 立刻判非法。粗略直觉：增长跑赢利率的「永动机」路径，就是被这道条件关掉的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不线性化、不谈根的计数。也不把 TVC 写成「债务必须还清」的道德：它是最优性条件，开放经济与Overlapping generations 里可以有不同的可行庞氏区，后课主权债再碰。连续时间对应 \\(\\lim e^{-\\rho t}u&#39;(c)k=0\\)，不重推。</p><p>后课默认：内部路径 = 欧拉 + 横截/有界；约束路径另标乘子。下一课把非线性欧拉收成对数线性，为 BK 准备方程组。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欧拉刻画相邻交换；横截关掉爆炸与庞氏。</li><li>有界性在线性系统里常替代显式 TVC。</li><li>值函数方法隐含这两条；方程方法必须分开写。</li><li>出处：Ramsey 1928；Stokey and Lucas with Prescott 1989。</li></ul>',8))])}const V=i(d,[["render",m]]);export{D as __pageData,V as default};
